package com.example.payment.infrastructure.contacts;

import com.example.payment.application.contacts.ContactStore;
import com.example.payment.domain.contacts.Contact;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/** Keeps contacts in memory; they are lost on restart. */
public final class InMemoryContactStore implements ContactStore {

    private final Map<String, Contact> contacts = new ConcurrentHashMap<>();

    @Override
    public void save(Contact contact) {
        contacts.put(contact.id(), contact);
    }

    @Override
    public Optional<Contact> findById(String id) {
        return Optional.ofNullable(contacts.get(id));
    }
}
