package com.example.payment.app;

import com.example.payment.application.contacts.CreateContact;
import com.example.payment.application.contacts.GetContact;
import com.example.payment.domain.contacts.Contact;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@RestController
class ContactController {

    record CreateContactRequest(String name, String email) {
    }

    private final CreateContact createContact;
    private final GetContact getContact;

    ContactController(CreateContact createContact, GetContact getContact) {
        this.createContact = createContact;
        this.getContact = getContact;
    }

    @PostMapping("/contacts")
    ResponseEntity<Contact> create(@RequestBody CreateContactRequest request) {
        var contact = createContact.handle(request.name(), request.email());
        return ResponseEntity.created(java.net.URI.create("/contacts/" + contact.id())).body(contact);
    }

    @GetMapping("/contacts/{id}")
    ResponseEntity<Contact> get(@PathVariable String id) {
        return getContact.handle(id).map(ResponseEntity::ok).orElseGet(() -> ResponseEntity.notFound().build());
    }
}
